package com.bank.perf.service;

// Generates a statement two ways: slow N+1 vs fast batched (each query simulated as 1ms).
public class StatementService {

    private static final long QUERY_COST_MS = 1; // each DB round-trip ~1ms (simulated)

    // SLOW: one query per transaction — the N+1 bottleneck.
    public int generateSlow(String accountId, int txnCount) {
        int rows = 0;
        rows += simulateQuery();                 // 1 query to load the account
        for (int i = 0; i < txnCount; i++) {
            rows += simulateQuery();             // +1 query PER transaction (N+1!)
        }
        return rows;
    }

    // FAST: one query for the account + one batched query for all transactions.
    public int generateFast(String accountId, int txnCount) {
        int rows = 0;
        rows += simulateQuery();                 // 1 query to load the account
        rows += simulateQuery();                 // 1 batched query for ALL transactions
        return rows + txnCount;                  // same data, two round-trips total
    }

    private int simulateQuery() {
        try { Thread.sleep(QUERY_COST_MS); } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return 1;
    }
}
