package com.bank.perf.service;

import java.util.logging.*;

// Times the slow and fast paths and reports a verified before/after improvement.
public class PerformanceHarness {
    private final Logger log;
    private final StatementService service;

    public PerformanceHarness(Logger log, StatementService service) {
        this.log = log;
        this.service = service;
    }

    public void compare(String accountId, int txnCount) {
        // MEASURE the slow path first — never optimize before measuring.
        long t0 = System.currentTimeMillis();
        service.generateSlow(accountId, txnCount);
        long slowMs = System.currentTimeMillis() - t0;
        log.warning(() -> "SLOW (N+1): " + slowMs + "ms for " + txnCount + " txns");

        // MEASURE the fast path (batched query).
        long t1 = System.currentTimeMillis();
        service.generateFast(accountId, txnCount);
        long fastMs = System.currentTimeMillis() - t1;
        log.info(() -> "FAST (batched): " + fastMs + "ms for " + txnCount + " txns");

        // VERIFY the improvement with a concrete speedup.
        long speedup = fastMs == 0 ? slowMs : slowMs / Math.max(fastMs, 1);
        log.info(() -> "IMPROVEMENT: ~" + speedup + "x faster ("
            + slowMs + "ms to " + fastMs + "ms)");
    }
}
